package dev.rajeev.shortener.domain;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.Instant;

/**
 * Create request. Bean Validation annotations document the contract and fail fast at the edge;
 * {@link LinkService} re-validates explicitly so the rules hold for every caller (not only HTTP).
 */
public record CreateLinkRequest(
        @NotBlank @Size(max = 8192) String url,
        @Pattern(regexp = LinkRules.CUSTOM_ALIAS_REGEX, message = "alias must be 4-32 URL-safe characters") String customAlias,
        @Size(max = 128) String ownerId,
        /** Optional hard expiry (ISO-8601). Must be in the future at creation; enforced in LinkService. */
        Instant expiresAt) {}

package dev.rajeev.shortener.domain;

import java.time.Instant;

/**
 * A short link. {@code code} is the public identifier: either generated (base62, see
 * {@link RandomCodeGenerator}) or a user-supplied custom alias. Soft-deleted links keep their
 * row so a code is never reissued and analytics remain readable.
 */
public record Link(
        String code,
        String targetUrl,
        Instant createdAt,
        Instant deletedAt,
        /** Optional hard expiry. After this instant the link answers 410 EXPIRED; stats stay readable. */
        Instant expiresAt,
        boolean custom,
        String ownerId) {

    public boolean deleted() {
        return deletedAt != null;
    }

    public boolean expiredAt(Instant now) {
        return expiresAt != null && !now.isBefore(expiresAt);
    }

    public Link withDeletedAt(Instant at) {
        return new Link(code, targetUrl, createdAt, at, expiresAt, custom, ownerId);
    }
}

package dev.rajeev.shortener.domain;

import java.time.Instant;

public record LinkResponse(String code, String shortUrl, String targetUrl, Instant createdAt, Instant expiresAt, boolean custom) {

    public static LinkResponse from(Link link, String baseUrl) {
        String base = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
        return new LinkResponse(link.code(), base + "/" + link.code(), link.targetUrl(), link.createdAt(), link.expiresAt(), link.custom());
    }
}

package dev.rajeev.shortener.domain;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.analytics.ClickEvent;
import dev.rajeev.shortener.analytics.ClickNormalizer;
import dev.rajeev.shortener.repository.AliasTakenException;
import dev.rajeev.shortener.repository.LinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.util.Locale;

/**
 * Application service: owns the use cases, knows nothing about HTTP. Routes are a thin adapter
 * over this class, which is what makes behaviour testable without a server and what lets the
 * orchestrator's impact analysis point at one module when a rule changes.
 */
public class LinkService {

    public record CreateResult(Link link, boolean created) {}

    private final LinkRepository repo;
    private final CodeGenerator codegen;
    private final AnalyticsQueue analytics;
    private final UrlPolicy urlPolicy;
    private final Clock clock;

    public LinkService(LinkRepository repo, CodeGenerator codegen, AnalyticsQueue analytics, UrlPolicy urlPolicy, Clock clock) {
        this.repo = repo;
        this.codegen = codegen;
        this.analytics = analytics;
        this.urlPolicy = urlPolicy;
        this.clock = clock;
    }

    public CreateResult create(CreateLinkRequest req, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = repo.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) return new CreateResult(existing.get(), false);
        }
        validate(req);

        String normalized = switch (urlPolicy.evaluate(req.url())) {
            case UrlPolicy.Ok ok -> ok.normalized();
            case UrlPolicy.Rejected rejected -> throw new DomainException(rejected.code(), rejected.message());
        };

        String code;
        if (req.customAlias() != null) {
            if (LinkRules.RESERVED_CODES.contains(req.customAlias().toLowerCase(Locale.ROOT))) {
                throw new DomainException(ErrorCode.ALIAS_RESERVED, "'" + req.customAlias() + "' is reserved");
            }
            code = req.customAlias();
        } else {
            try {
                code = codegen.generate(repo::exists);
            } catch (CodeExhaustedException e) {
                throw new DomainException(ErrorCode.CODE_EXHAUSTED, e.getMessage());
            }
        }

        Link link = new Link(code, normalized, clock.instant(), null, req.expiresAt(), req.customAlias() != null, req.ownerId());
        try {
            repo.insert(link);
        } catch (AliasTakenException e) {
            throw new DomainException(ErrorCode.ALIAS_TAKEN, e.getMessage());
        }
        if (idempotencyKey != null && !idempotencyKey.isBlank()) repo.rememberIdempotencyKey(idempotencyKey, code, clock.instant());
        return new CreateResult(link, true);
    }

    /** Explicit validation so the rules hold for every caller, not only for @Valid at the HTTP edge. */
    private static void validate(CreateLinkRequest req) {
        if (req == null || req.url() == null || req.url().isBlank()) throw new DomainException(ErrorCode.VALIDATION, "url is required");
        if (req.url().length() > 8192) throw new DomainException(ErrorCode.VALIDATION, "url is too long");
        if (req.customAlias() != null && !LinkRules.CUSTOM_ALIAS_PATTERN.matcher(req.customAlias()).matches()) {
            throw new DomainException(ErrorCode.VALIDATION, "alias must be 4-32 URL-safe characters");
        }
        if (req.ownerId() != null && req.ownerId().length() > 128) throw new DomainException(ErrorCode.VALIDATION, "ownerId is too long");
    }

    /** Returns the active link or throws NOT_FOUND / GONE. */
    public Link resolve(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has been deleted");
        return link;
    }

    /** Resolve + fire-and-forget analytics. Redirect latency never waits on the store. */
    public Link resolveAndTrack(String code, String referrer, String userAgent) {
        Link link = resolve(code);
        analytics.enqueue(new ClickEvent(link.code(), clock.instant(), ClickNormalizer.referrer(referrer), ClickNormalizer.userAgent(userAgent)));
        return link;
    }

    public Link get(String code) {
        return resolve(code);
    }

    public void remove(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has already been deleted");
        repo.softDelete(code, clock.instant());
    }

    public LinkStats stats(String code, int days, int topN) {
        repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        // Stats stay readable after deletion: owners often want the final numbers.
        analytics.flush();
        return repo.stats(code, days, topN);
    }
}

package dev.rajeev.shortener.repository;

import dev.rajeev.shortener.analytics.ClickEvent;
import dev.rajeev.shortener.domain.Link;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * JdbcTemplate adapter for H2 (dev/test) and PostgreSQL (prod) — same SQL. No ORM: a two-table
 * schema with a hot write path is clearer as explicit SQL, and the batch insert in one transaction is
 * the difference between hundreds and tens of thousands of click inserts per second.
 *
 * Uniqueness of {@code code} is enforced by the primary key: the application-level {@code exists()}
 * check is an optimisation; two concurrent inserts of the same alias still resolve correctly.
 */
public class JdbcLinkRepository implements LinkRepository {

    private static final RowMapper<Link> LINK_ROW = (rs, i) -> new Link(
            rs.getString("code"),
            rs.getString("target_url"),
            instant(rs, "created_at"),
            instant(rs, "deleted_at"),
            instant(rs, "expires_at"),
            rs.getBoolean("custom"),
            rs.getString("owner_id"));

    private final JdbcTemplate jdbc;
    private final TransactionTemplate tx;
    private final Clock clock;

    public JdbcLinkRepository(JdbcTemplate jdbc, TransactionTemplate tx, Clock clock) {
        this.jdbc = jdbc;
        this.tx = tx;
        this.clock = clock;
        new SchemaMigrator(jdbc).migrate();
    }

    private static Instant instant(ResultSet rs, String column) throws SQLException {
        Timestamp ts = rs.getTimestamp(column);
        return ts == null ? null : ts.toInstant();
    }

    private static Timestamp ts(Instant i) {
        return i == null ? null : Timestamp.from(i);
    }

    @Override
    public void insert(Link link) {
        try {
            jdbc.update("INSERT INTO links(code, target_url, created_at, deleted_at, expires_at, custom, owner_id) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    link.code(), link.targetUrl(), ts(link.createdAt()), ts(link.deletedAt()), ts(link.expiresAt()), link.custom(), link.ownerId());
        } catch (DuplicateKeyException e) {
            throw new AliasTakenException(link.code());
        }
    }

    @Override
    public Optional<Link> findByCode(String code) {
        return jdbc.query("SELECT code, target_url, created_at, deleted_at, expires_at, custom, owner_id FROM links WHERE code = ?", LINK_ROW, code)
                .stream().findFirst();
    }

    @Override
    public boolean exists(String code) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM links WHERE code = ?", Integer.class, code);
        return n != null && n > 0;
    }

    @Override
    public boolean softDelete(String code, Instant at) {
        return jdbc.update("UPDATE links SET deleted_at = ? WHERE code = ? AND deleted_at IS NULL", ts(at), code) > 0;
    }

    @Override
    public Optional<Link> findByIdempotencyKey(String key) {
        return jdbc.query("SELECT code FROM idempotency_keys WHERE idem_key = ?", (rs, i) -> rs.getString(1), key)
                .stream().findFirst().flatMap(this::findByCode);
    }

    @Override
    public void rememberIdempotencyKey(String key, String code, Instant at) {
        try {
            jdbc.update("INSERT INTO idempotency_keys(idem_key, code, created_at) VALUES (?, ?, ?)", key, code, ts(at));
        } catch (DuplicateKeyException ignored) {
            // a concurrent request with the same key won; both callers observe the same link
        }
    }

    @Override
    public void recordClicks(List<ClickEvent> events) {
        if (events.isEmpty()) return;
        tx.executeWithoutResult(status -> jdbc.batchUpdate(
                "INSERT INTO clicks(code, occurred_at, referrer, user_agent) VALUES (?, ?, ?, ?)",
                events,
                events.size(),
                (ps, e) -> {
                    ps.setString(1, e.code());
                    ps.setTimestamp(2, ts(e.occurredAt()));
                    ps.setString(3, e.referrer());
                    ps.setString(4, e.userAgent());
                }));
    }

    @Override
    public LinkStats stats(String code, int days, int topN) {
        Timestamp cutoff = ts(clock.instant().minus(days, ChronoUnit.DAYS));
        record Totals(long n, Instant last) {}
        Totals totals = jdbc.queryForObject("SELECT COUNT(*) AS n, MAX(occurred_at) AS last FROM clicks WHERE code = ?",
                (rs, i) -> new Totals(rs.getLong("n"), instant(rs, "last")), code);
        List<LinkStats.DayCount> byDay = jdbc.query(
                "SELECT CAST(occurred_at AS DATE) AS click_day, COUNT(*) AS clicks FROM clicks WHERE code = ? AND occurred_at >= ? GROUP BY CAST(occurred_at AS DATE) ORDER BY click_day",
                (rs, i) -> new LinkStats.DayCount(rs.getDate("click_day").toLocalDate().toString(), rs.getLong("clicks")), code, cutoff);
        List<LinkStats.ReferrerCount> byRef = jdbc.query(
                "SELECT referrer, COUNT(*) AS clicks FROM clicks WHERE code = ? AND occurred_at >= ? GROUP BY referrer ORDER BY clicks DESC, referrer ASC LIMIT ?",
                (rs, i) -> new LinkStats.ReferrerCount(rs.getString("referrer"), rs.getLong("clicks")), code, cutoff, topN);
        List<LinkStats.UserAgentCount> byUa = jdbc.query(
                "SELECT user_agent, COUNT(*) AS clicks FROM clicks WHERE code = ? AND occurred_at >= ? GROUP BY user_agent ORDER BY clicks DESC, user_agent ASC LIMIT ?",
                (rs, i) -> new LinkStats.UserAgentCount(rs.getString("user_agent"), rs.getLong("clicks")), code, cutoff, topN);
        return new LinkStats(code, totals == null ? 0 : totals.n(), byDay, byRef, byUa, totals == null ? null : totals.last());
    }

    @Override
    public void ping() {
        jdbc.queryForObject("SELECT 1", Integer.class);
    }
}

package dev.rajeev.shortener.repository;

import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * Versioned, idempotent, in-code schema migration. Small enough at v1 to keep explicit; a Flyway
 * migration set is the drop-in replacement once the schema grows (documented in the limitations).
 * SQL is kept to the H2/PostgreSQL common subset.
 */
public class SchemaMigrator {

    private static final Logger log = LoggerFactory.getLogger(SchemaMigrator.class);
    public static final int CURRENT_VERSION = 2;

    private final JdbcTemplate jdbc;

    public SchemaMigrator(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public int migrate() {
        jdbc.execute("CREATE TABLE IF NOT EXISTS schema_version (version INTEGER NOT NULL)");
        Integer version = jdbc.query("SELECT version FROM schema_version", rs -> rs.next() ? rs.getInt(1) : null);
        if (version == null) {
            createV1();
            jdbc.update("INSERT INTO schema_version(version) VALUES (1)");
            version = 1;
        }
        if (version < 2) {
            migrateToV2();
            version = 2;
        }
        log.info("schema version {}", version);
        return version;
    }

    /**
     * v2: optional expiry. Additive nullable column, so v1 rows keep working untouched and the migration
     * is safe to run on a live database. Rolling the code back leaves the column in place, which v1
     * ignores — forward-compatible.
     */
    private void migrateToV2() {
        boolean present = Boolean.TRUE.equals(jdbc.query(
                "SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE UPPER(TABLE_NAME) = 'LINKS' AND UPPER(COLUMN_NAME) = 'EXPIRES_AT'",
                rs -> rs.next() && rs.getInt(1) > 0));
        if (!present) jdbc.execute("ALTER TABLE links ADD COLUMN expires_at TIMESTAMP");
        jdbc.update("UPDATE schema_version SET version = 2");
    }

    private void createV1() {
        for (String ddl : List.of(
                """
                CREATE TABLE IF NOT EXISTS links (
                  code        VARCHAR(32)   PRIMARY KEY,
                  target_url  VARCHAR(8192) NOT NULL,
                  created_at  TIMESTAMP     NOT NULL,
                  deleted_at  TIMESTAMP,
                  custom      BOOLEAN       NOT NULL DEFAULT FALSE,
                  owner_id    VARCHAR(128)
                )""",
                """
                CREATE TABLE IF NOT EXISTS idempotency_keys (
                  idem_key    VARCHAR(128) PRIMARY KEY,
                  code        VARCHAR(32)  NOT NULL,
                  created_at  TIMESTAMP    NOT NULL
                )""",
                """
                CREATE TABLE IF NOT EXISTS clicks (
                  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                  code        VARCHAR(32)  NOT NULL,
                  occurred_at TIMESTAMP    NOT NULL,
                  referrer    VARCHAR(255) NOT NULL,
                  user_agent  VARCHAR(64)  NOT NULL
                )""",
                "CREATE INDEX IF NOT EXISTS idx_clicks_code_time ON clicks(code, occurred_at)")) {
            jdbc.execute(ddl);
        }
    }
}

package dev.rajeev.shortener.domain;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.repository.InMemoryLinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.function.Predicate;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class LinkServiceTest {

    /** Test clock that advances one second per read, so ordering is deterministic. */
    static class TickingClock extends Clock {
        private Instant now = Instant.now().minusSeconds(60);

        @Override public ZoneOffset getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(java.time.ZoneId zone) { return this; }
        @Override public Instant instant() { now = now.plusSeconds(1); return now; }
    }

    static class QueuedCodes implements CodeGenerator {
        final Deque<String> codes = new ArrayDeque<>(List.of("gen0001", "gen0002", "gen0003"));

        @Override
        public String generate(Predicate<String> exists) {
            while (!codes.isEmpty()) {
                String c = codes.pop();
                if (!exists.test(c)) return c;
            }
            throw new IllegalStateException("out of test codes");
        }
    }

    private final InMemoryLinkRepository repo = new InMemoryLinkRepository();
    private final AnalyticsQueue analytics = new AnalyticsQueue(repo, 10_000, 10, 100, 3);
    private final LinkService service = new LinkService(repo, new QueuedCodes(), analytics, new UrlPolicy(2048, List.of("localhost:8080"), false), new TickingClock());

    @AfterEach
    void tearDown() {
        analytics.close();
    }

    private static ErrorCode codeOf(Runnable r) {
        DomainException e = assertThrows(DomainException.class, r::run);
        return e.code();
    }

    @Test
    void createsALinkWithAGeneratedCode() {
        var result = service.create(new CreateLinkRequest("https://example.com", null, null, null), null);
        assertTrue(result.created());
        assertEquals("gen0001", result.link().code());
        assertEquals("https://example.com/", result.link().targetUrl());
        assertFalse(result.link().custom());
        assertNull(result.link().deletedAt());
    }

    @Test
    void usesACustomAliasWhenGiven() {
        var result = service.create(new CreateLinkRequest("https://example.com", "my-link", "owner-1", null), null);
        assertEquals("my-link", result.link().code());
        assertTrue(result.link().custom());
        assertEquals("owner-1", result.link().ownerId());
    }

    @Test
    void rejectsTakenReservedAndInvalidAliases() {
        service.create(new CreateLinkRequest("https://example.com", "taken1", null, null), null);
        assertEquals(ErrorCode.ALIAS_TAKEN, codeOf(() -> service.create(new CreateLinkRequest("https://other.com", "taken1", null, null), null)));
        assertEquals(ErrorCode.ALIAS_RESERVED, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "health", null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "a b", null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("", null, null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", null, "x".repeat(200), null), null)));
    }

    @Test
    void rejectsDisallowedUrlsWithThePolicyReason() {
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("javascript:alert(1)", null, null, null), null)));
        assertEquals(ErrorCode.INVALID_URL, codeOf(() -> service.create(new CreateLinkRequest("nope", null, null, null), null)));
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("http://localhost:8080/x", null, null, null), null)));
    }

    @Test
    void isIdempotentOnIdempotencyKey() {
        var a = service.create(new CreateLinkRequest("https://example.com", null, null, null), "key-1");
        var b = service.create(new CreateLinkRequest("https://example.com", null, null, null), "key-1");
        assertTrue(a.created());
        assertFalse(b.created());
        assertEquals(a.link().code(), b.link().code());
    }

    @Test
    void mapsCodeExhaustionToCodeExhausted() {
        LinkService exhausted = new LinkService(repo, exists -> { throw new CodeExhaustedException(5); }, analytics, new UrlPolicy(2048, List.of(), false), Clock.systemUTC());
        assertEquals(ErrorCode.CODE_EXHAUSTED, codeOf(() -> exhausted.create(new CreateLinkRequest("https://example.com", null, null, null), null)));
    }

    @Test
    void resolvesActiveLinksAndTracksClicksAsynchronously() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        Link resolved = service.resolveAndTrack(link.code(), "https://news.ycombinator.com/", "curl/8");
        assertEquals("https://example.com/", resolved.targetUrl());
        assertEquals(1, analytics.metrics().enqueued());
        LinkStats stats = service.stats(link.code(), 30, 5);
        assertEquals(1, stats.totalClicks());
        assertEquals(List.of(new LinkStats.ReferrerCount("news.ycombinator.com", 1)), stats.topReferrers());
        assertEquals(List.of(new LinkStats.UserAgentCount("curl", 1)), stats.topUserAgents());
    }

    @Test
    void returnsNotFoundForUnknownAndGoneForDeleted() {
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.resolve("missing")));
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        service.remove(link.code());
        assertEquals(ErrorCode.GONE, codeOf(() -> service.resolve(link.code())));
        assertEquals(ErrorCode.GONE, codeOf(() -> service.remove(link.code())));
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.remove("missing")));
    }

    @Test
    void keepsStatsReadableAfterDeletion() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        service.resolveAndTrack(link.code(), null, null);
        service.remove(link.code());
        assertEquals(1, service.stats(link.code(), 30, 5).totalClicks());
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.stats("missing", 30, 5)));
    }
}

package dev.rajeev.shortener.repository;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.rajeev.shortener.analytics.ClickEvent;
import dev.rajeev.shortener.domain.Link;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Contract every LinkRepository adapter must satisfy. Adding Postgres later means adding one
 * subclass, nothing else.
 */
abstract class LinkRepositoryContractTest {

    protected LinkRepository repo;

    protected abstract LinkRepository createRepository();

    protected void cleanup() {}

    @BeforeEach
    void setUp() {
        repo = createRepository();
    }

    @AfterEach
    void tearDown() {
        cleanup();
    }

    static Link link(String code) {
        return new Link(code, "https://example.com/", Instant.parse("2026-01-01T00:00:00Z"), null, null, false, null);
    }

    @Test
    void persistsAnOptionalExpiry() {
        Instant expires = Instant.parse("2030-01-01T00:00:00Z");
        repo.insert(new Link("exp1234", "https://example.com/", Instant.parse("2026-01-01T00:00:00Z"), null, expires, false, null));
        assertEquals(expires, repo.findByCode("exp1234").orElseThrow().expiresAt());
        repo.insert(link("noexp12"));
        assertNull(repo.findByCode("noexp12").orElseThrow().expiresAt());
    }

    @Test
    void insertsAndFindsALink() {
        Link l = new Link("abc1234", "https://example.com/", Instant.parse("2026-01-01T00:00:00Z"), null, null, true, "u1");
        repo.insert(l);
        assertEquals(l, repo.findByCode("abc1234").orElseThrow());
        assertTrue(repo.exists("abc1234"));
        assertFalse(repo.exists("nope"));
        assertTrue(repo.findByCode("nope").isEmpty());
    }

    @Test
    void rejectsDuplicateCodesAtomically() {
        repo.insert(link("dup1234"));
        assertThrows(AliasTakenException.class, () -> repo.insert(link("dup1234")));
    }

    @Test
    void softDeletesOnceAndKeepsTheCodeReserved() {
        repo.insert(link("del1234"));
        Instant at = Instant.parse("2026-02-01T00:00:00Z");
        assertTrue(repo.softDelete("del1234", at));
        assertFalse(repo.softDelete("del1234", Instant.parse("2026-02-02T00:00:00Z")));
        assertEquals(at, repo.findByCode("del1234").orElseThrow().deletedAt());
        assertThrows(AliasTakenException.class, () -> repo.insert(link("del1234")));
        assertFalse(repo.softDelete("missing", at));
    }

    @Test
    void remembersIdempotencyKeys() {
        repo.insert(link("idem123"));
        assertTrue(repo.findByIdempotencyKey("k1").isEmpty());
        repo.rememberIdempotencyKey("k1", "idem123", Instant.now());
        repo.rememberIdempotencyKey("k1", "idem123", Instant.now()); // repeat is a no-op
        assertEquals("idem123", repo.findByIdempotencyKey("k1").orElseThrow().code());
    }

    @Test
    void aggregatesClickStats() {
        repo.insert(link("stat123"));
        Instant today = Instant.now().truncatedTo(ChronoUnit.MILLIS);
        Instant yesterday = today.minus(1, ChronoUnit.DAYS);
        Instant ancient = Instant.parse("2020-01-01T00:00:00Z");
        repo.recordClicks(List.of(
                new ClickEvent("stat123", today, "a.com", "Chrome"),
                new ClickEvent("stat123", today, "a.com", "curl"),
                new ClickEvent("stat123", yesterday, "b.com", "Chrome"),
                new ClickEvent("stat123", ancient, "old.com", "Bot"),
                new ClickEvent("other12", today, "z.com", "Chrome")));
        LinkStats s = repo.stats("stat123", 30, 1);
        assertEquals("stat123", s.code());
        assertEquals(4, s.totalClicks()); // total counts everything ever
        assertEquals(3, s.clicksByDay().stream().mapToLong(LinkStats.DayCount::clicks).sum()); // window excludes the ancient click
        assertEquals(List.of(new LinkStats.ReferrerCount("a.com", 2)), s.topReferrers());
        assertEquals(List.of(new LinkStats.UserAgentCount("Chrome", 2)), s.topUserAgents());
        assertEquals(today, s.lastClickAt());
    }

    @Test
    void returnsEmptyStatsForAnUnclickedCode() {
        LinkStats s = repo.stats("never12", 30, 5);
        assertEquals(0, s.totalClicks());
        assertTrue(s.clicksByDay().isEmpty());
        assertTrue(s.topReferrers().isEmpty());
        assertNull(s.lastClickAt());
    }

    @Test
    void emptyBatchIsANoOpAndPingWorks() {
        repo.recordClicks(List.of());
        repo.ping();
    }
}

package dev.rajeev.shortener.repository;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;

class SchemaMigratorTest {

    private static JdbcTemplate fresh() {
        org.h2.jdbcx.JdbcDataSource ds = new org.h2.jdbcx.JdbcDataSource();
        ds.setURL("jdbc:h2:mem:" + UUID.randomUUID() + ";MODE=PostgreSQL;DB_CLOSE_DELAY=-1");
        return new JdbcTemplate(ds);
    }

    @Test
    void createsTheSchemaOnceAndIsIdempotent() {
        JdbcTemplate jdbc = fresh();
        assertEquals(SchemaMigrator.CURRENT_VERSION, new SchemaMigrator(jdbc).migrate());
        assertEquals(SchemaMigrator.CURRENT_VERSION, new SchemaMigrator(jdbc).migrate());
        assertEquals(Integer.valueOf(1), jdbc.queryForObject("SELECT COUNT(*) FROM schema_version", Integer.class));
        assertEquals(Integer.valueOf(2), jdbc.queryForObject("SELECT version FROM schema_version", Integer.class));
        assertEquals(Integer.valueOf(0), jdbc.queryForObject("SELECT COUNT(*) FROM links", Integer.class));
    }
}
